import { ImageResponse } from "next/og";

export const alt = "Rajeev Puri - Software Engineer";

export const size = {
	width: 1200,
	height: 630,
};

export const contentType = "image/png";

export default async function Image() {
	return new ImageResponse(
		(
			<div
				style={{
					width: "100%",
					height: "100%",
					display: "flex",
					alignItems: "stretch",
					justifyContent: "space-between",
					background:
						"radial-gradient(circle at top left, rgba(255,255,255,0.18), transparent 34%), linear-gradient(135deg, #050505 0%, #0b0b0d 45%, #111216 100%)",
					color: "white",
					fontFamily: "Inter, Arial, sans-serif",
					padding: 48,
					position: "relative",
				}}
			>
				<div
					style={{
						position: "absolute",
						inset: 0,
						opacity: 0.18,
						background:
							"linear-gradient(90deg, rgba(255,255,255,0.08) 1px, transparent 1px), linear-gradient(rgba(255,255,255,0.08) 1px, transparent 1px)",
						backgroundSize: "48px 48px",
						maskImage:
							"radial-gradient(circle at center, black 42%, transparent 100%)",
					}}
				/>

				<div
					style={{
						display: "flex",
						flexDirection: "column",
						justifyContent: "space-between",
						width: "100%",
						height: "100%",
						position: "relative",
						zIndex: 1,
					}}
				>
					<div
						style={{
							display: "flex",
							alignItems: "center",
							justifyContent: "space-between",
							fontSize: 22,
							letterSpacing: "0.18em",
							textTransform: "uppercase",
							color: "rgba(255,255,255,0.72)",
						}}
					>
						<span>Rajeev Puri</span>
						<span>Software Engineer</span>
					</div>

					<div
						style={{
							display: "flex",
							flexDirection: "column",
							gap: 24,
							maxWidth: 820,
						}}
					>
						<div
							style={{
								display: "flex",
								alignItems: "center",
								gap: 12,
								fontSize: 20,
								fontWeight: 600,
								color: "rgba(255,255,255,0.8)",
							}}
						>
							<span
								aria-hidden="true"
								style={{
									width: 12,
									height: 12,
									borderRadius: 9999,
									background: "#d4af37",
									boxShadow: "0 0 0 6px rgba(212,175,55,0.12)",
								}}
							>
								•
							</span>
							<span>London, UK</span>
						</div>

						<h1
							style={{
								fontSize: 72,
								lineHeight: 0.95,
								fontWeight: 800,
								letterSpacing: "-0.05em",
								maxWidth: 860,
								margin: 0,
							}}
						>
							Full-Stack Engineer
							<br />
							Next.js, React & TypeScript
						</h1>

						<p
							style={{
								fontSize: 28,
								lineHeight: 1.35,
								maxWidth: 760,
								margin: 0,
								color: "rgba(255,255,255,0.74)",
							}}
						>
							Building high-performance web apps, scalable systems, and clean digital experiences.
						</p>
					</div>

					<div
						style={{
							display: "flex",
							justifyContent: "space-between",
							alignItems: "center",
							fontSize: 18,
							color: "rgba(255,255,255,0.66)",
						}}
					>
						<span>rajeevpuri.com.np</span>
						<span>Portfolio · Blog · Projects</span>
					</div>
				</div>
			</div>
		),
		{
			...size,
		}
	);
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}
